SQL_DOC.P_SQL:
DECLARE V_CNT NUMBER; BEGIN SELECT COUNT(*) INTO V_CNT FROM TBL_KEP_PRICE WHERE PLANT = $PLANT$ AND QUOTATION_NO = $QUOTATION_NO$ AND QUOTATION_SEQ = $QUOTATION_SEQ$ AND REVISION_NO = $REVISION_NO$ ;
IF V_CNT = 0 THEN INSERT INTO TBL_KEP_PRICE ( PLANT , QUOTATION_NO , QUOTATION_SEQ , REVISION_NO , BUYER_ITEM_NO , UNIT_PRICE , MAKER_NAME , UNIT_PRICE2 , MAKER_NAME2 , UNIT_PRICE3 , MAKER_NAME3 , ZCOMMENT , PISTAT , IF_DATE
) VALUES ( $PLANT$ , $QUOTATION_NO$ , $QUOTATION_SEQ$ , $REVISION_NO$ , $BUYER_ITEM_NO$ , $UNIT_PRICE$ , $MAKER_NAME$ , $UNIT_PRICE2$ , $MAKER_NAME2$ , $UNIT_PRICE3$ , $MAKER_NAME3$ , $ZCOMMENT$ , 'R' , SYSDATE ); END IF;
END;
